import{_ as a,c as e,o as t,af as i}from"./chunks/framework.BKeRpnBD.js";const h=JSON.parse('{"title":"《杂卦传》简介","description":"易传 - 《杂卦传》简介","frontmatter":{"title":"《杂卦传》简介","description":"易传 - 《杂卦传》简介"},"headers":[],"relativePath":"zh/classics/yizhuan/006.md","filePath":"zh/classics/yizhuan/006.md"}'),s={name:"zh/classics/yizhuan/006.md"};function l(r,p,n,c,_,o){return t(),e("div",null,[...p[0]||(p[0]=[i('<h1 id="《杂卦传》简介" tabindex="-1">《杂卦传》简介 <a class="header-anchor" href="#《杂卦传》简介" aria-label="Permalink to “《杂卦传》简介”">​</a></h1><p>其功能作用主要体现在对《周易》六十四卦卦义及相互关系的精炼总结与点评。它打乱了六十四卦的常规排列顺序，以两两相对的方式，用极其凝炼的语言归纳了各卦的卦义，使得原本纷繁复杂的卦象变得简洁明了，易于记忆。</p><p>此外，《杂卦传》还通过对比各卦之间的异同，帮助读者深入理解各卦的内涵及其相互关系。这种以对比方式进行的学习，有助于读者培养反向思维和全面观察事物的能力，从而更全面地把握《周易》的精髓。</p><p>杂卦传</p><p>《乾》刚《坤》柔，《比》乐《师》忧；《临》《观》之义，或与或求。</p><p>《屯》见而不失其居。《蒙》杂而著。《震》，起也。《艮》，止也。《损》、《益》盛衰之始也。</p><p>《大畜》，时也。《无妄》，灾也。《萃》聚而《升》不来也。《谦》轻而《豫》怠也。</p><p>《噬嗑》，食也。《贲》，无色也。《兑》见而《巽》伏也。《随》无故也。《蛊》则饬也。</p><p>《剥》，烂也。《复》，反也。《晋》，昼也。《明夷》，诛也。《井》通而《困》相遇也。</p><p>《咸》速也。《恒》，久也。《涣》，离也。《节》，止也。《解》，缓也。《蹇》，难也。</p><p>《睽》，外也。《家人》，内也。《否》、《泰》反其类也。《大壮》则止，《遯》则退也。</p><p>《大有》，众也。《同人》，亲也。《革》，去故也。《鼎》，取新也。</p><p>《小过》，过也。《中孚》，信也。《丰》，多故也。亲寡《旅》也。</p><p>《离》上而《坎》下也。《小畜》，寡也。《履》，不处也。《需》，不进也。</p><p>《讼》，不亲也。《大过》，颠也。《姤》，遇也，柔遇刚也。《渐》，女归待男行也。</p><p>《颐》，养正也。《既济》，定也。《归妹》，女之终也。《未济》，男之穷也。</p><p>《夬》，决也，刚决柔也。君子道长，小人道忧也。</p><p>《杂卦传》要说明了《易经》六十四卦之间的错综关系，以相反相成的观点将六十四卦分为三十二对，两两一组进行解释，揭示了各卦的卦义和相互关系。</p><p>《杂卦传》特征</p><ul><li><p>分类解读 ：以相反或相成的观点，将六十四卦分为三十二对，每对卦象通过一两个字来概括其主要含义和相互关系。</p></li><li><p>言简意赅 ：《杂卦传》的言辞非常简洁，或以一字释一卦，或数字释一卦，这种表述方式既精炼又富有哲理。</p></li><li><p>互补印证 ：《杂卦传》与《序卦传》互相补充印证，共同揭示了《易经》卦象之间的深刻内涵。</p></li></ul>',20)])])}const f=a(s,[["render",l]]);export{h as __pageData,f as default};
